mapper.select:
SELECT csv.community_no AS board_no, csv.title, csv.writer_id, csv.writer_name, csv.content_date, csv.content_status, csv.view_count, csv.like_count, csv.dislike_count, csv.comment_count, csv.report_count, csv.member_grade AS writer_grade, CASE WHEN cl.member_id IS NOT NULL THEN 1 ELSE 0 END AS is_liked, CASE WHEN cd.member_id IS NOT NULL THEN 1 ELSE 0 END AS is_disliked, CASE WHEN cc.community_comment_writer IS NOT NULL THEN 1 ELSE 0 END AS is_commented, CASE WHEN cr.member_id IS NOT NULL THEN 1 ELSE 0 END AS is_reported FROM community_summary_view csv LEFT JOIN community_like_tbl cl ON csv.community_no = cl.community_no AND cl.member_id = #{memberId} LEFT JOIN community_dislike_tbl cd ON csv.community_no = cd.community_no AND cd.member_id = #{memberId} LEFT JOIN ( SELECT community_no, MAX(community_comment_writer) AS community_comment_writer FROM community_comment_tbl WHERE community_comment_writer = #{memberId} GROUP BY community_no ) cc ON csv.community_no = cc.community_no LEFT JOIN community_report_tbl cr ON csv.community_no = cr.community_no AND cr.member_id = #{memberId}
csv.title LIKE CONCAT('%', #{searchKeyword}, '%')
AND csv.writer_id = #{memberId}
AND csv.member_grade IN (1, 2)
AND csv.content_status = #{status}
ORDER BY csv.content_date DESC, csv.community_no DESC ORDER BY csv.content_date ASC, csv.community_no ASC ORDER BY csv.view_count DESC, csv.community_no DESC ORDER BY csv.like_count DESC, csv.community_no DESC ORDER BY csv.dislike_count DESC, csv.community_no DESC ORDER BY csv.report_count DESC, csv.community_no DESC LIMIT #{size} OFFSET ${page*size}

SELECT COUNT(*) AS count
FROM community_summary_view csv
LEFT JOIN community_like_tbl cl
	ON csv.community_no = cl.community_no AND cl.member_id = #{memberId}
LEFT JOIN community_dislike_tbl cd
	ON csv.community_no = cd.community_no AND cd.member_id = #{memberId}
LEFT JOIN (
	SELECT community_no, MAX(community_comment_writer) AS community_comment_writer
	FROM community_comment_tbl
	WHERE community_comment_writer = #{memberId}
	GROUP BY community_no
) cc ON csv.community_no = cc.community_no
LEFT JOIN community_report_tbl cr
	ON csv.community_no = cr.community_no AND cr.member_id = #{memberId}

	csv.title LIKE CONCAT('%', #{searchKeyword}, '%')

		AND csv.writer_id = #{memberId}


		AND csv.member_grade IN (1, 2)


		AND csv.content_status = #{status}

mapper.update:
UPDATE community_tbl
SET community_status = #{status}
WHERE community_no = #{boardNo}

mapper.select:
SELECT msv.market_no AS board_no, msv.title, msv.writer_id, msv.writer_name, msv.content_date, msv.content_status, msv.view_count, msv.like_count, msv.comment_count, msv.report_count, msv.completed AS is_completed, DATE_FORMAT(msv.completed_date, '%Y-%m-%d') AS completed_date, CASE WHEN cl.member_id IS NOT NULL THEN 1 ELSE 0 END AS is_liked, CASE WHEN cc.market_comment_writer IS NOT NULL THEN 1 ELSE 0 END AS is_commented, CASE WHEN cr.member_id IS NOT NULL THEN 1 ELSE 0 END AS is_reported FROM market_summary_view msv LEFT JOIN market_like_tbl cl ON msv.market_no = cl.market_no AND cl.member_id = #{memberId} LEFT JOIN ( SELECT market_no, MAX(market_comment_writer) AS market_comment_writer FROM market_comment_tbl WHERE market_comment_writer = #{memberId} GROUP BY market_no ) cc ON msv.market_no = cc.market_no LEFT JOIN market_report_tbl cr ON msv.market_no = cr.market_no AND cr.member_id = #{memberId}
msv.content_status != 3 AND msv.title LIKE CONCAT('%', #{searchKeyword}, '%')
AND msv.writer_id = #{memberId}
AND msv.content_status = #{status}
AND msv.completed = #{completed}
ORDER BY msv.content_date DESC, msv.market_no DESC ORDER BY msv.content_date ASC, msv.market_no ASC ORDER BY msv.view_count DESC, msv.market_no DESC ORDER BY msv.like_count DESC, msv.market_no DESC ORDER BY msv.report_count DESC, msv.market_no DESC
ORDER BY msv.completed_date IS NULL ASC, msv.completed_date DESC LIMIT #{size} OFFSET ${page*size}

SELECT COUNT(*) AS count
FROM market_summary_view msv
LEFT JOIN market_like_tbl cl
	ON msv.market_no = cl.market_no AND cl.member_id = #{memberId}
LEFT JOIN (
	SELECT market_no, MAX(market_comment_writer) AS market_comment_writer
	FROM market_comment_tbl
	WHERE market_comment_writer = #{memberId}
	GROUP BY market_no
) cc ON msv.market_no = cc.market_no
LEFT JOIN market_report_tbl cr
	ON msv.market_no = cr.market_no AND cr.member_id = #{memberId}

	msv.content_status != 3
	AND msv.title LIKE CONCAT('%', #{searchKeyword}, '%')

		AND msv.writer_id = #{memberId}


		AND msv.content_status = #{status}


		AND msv.completed = #{completed}

